// The type files "Sidestory: Add Widget Types" writes for widget authors (docs/WIDGETS-PLAN.md §2, §9),
// so `tsc` and IntelliSense work on widgets without installing packages. The .d.ts files here are shipped
// as they are; libraries.d.ts and lucide-react.d.ts are generated by scripts/widget-types.ts.
import { copyFile, mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

/** The declaration files, in this folder. */
export const WIDGET_TYPE_FILES = ['react.d.ts', 'explainer.d.ts', 'ui.d.ts', 'libraries.d.ts', 'lucide-react.d.ts'] as const;

/**
 * The `.sidestory/tsconfig.json` that goes with them. `typesDir` is where the declaration files are written,
 * relative to `.sidestory/` (for example `.types`).
 */
export function widgetTsconfig(typesDir: string): string {
  const config = {
    compilerOptions: {
      target: 'ES2022',
      lib: ['ES2022', 'DOM', 'DOM.Iterable'],
      module: 'ESNext',
      moduleResolution: 'Bundler',
      jsx: 'react-jsx',
      strict: true,
      noEmit: true,
      allowJs: true,
      checkJs: false,
      resolveJsonModule: true,
      esModuleInterop: true,
      allowSyntheticDefaultImports: true,
      isolatedModules: true,
      skipLibCheck: true,
      types: [],
      typeRoots: [],
    },
    include: [`${typesDir}/*.d.ts`, '*/**/*.tsx', '*/**/*.ts', '*/**/*.jsx'],
  };
  return `${JSON.stringify(config, null, 2)}\n`;
}

/**
 * Writes the declaration files (from `sourceDir`, where they ship: dist/widget-types) into
 * `<explainDir>/.types/` and the tsconfig into `<explainDir>/tsconfig.json`, for "Add Widget Types" and
 * `check.cjs --types`. Returns the paths written, relative to `explainDir`.
 */
export async function writeWidgetTypes(explainDir: string, sourceDir: string): Promise<string[]> {
  await mkdir(join(explainDir, '.types'), { recursive: true });
  for (const f of WIDGET_TYPE_FILES) await copyFile(join(sourceDir, f), join(explainDir, '.types', f));
  await writeFile(join(explainDir, 'tsconfig.json'), widgetTsconfig('.types'));
  return ['tsconfig.json', ...WIDGET_TYPE_FILES.map((f) => `.types/${f}`)];
}

/** How to typecheck once the files are there (TypeScript isn't shipped: npx fetches it). */
export const TYPECHECK_COMMAND = 'npx -y -p typescript tsc -p .sidestory';
